    12	/**
    13	 * The MHPCO insures two kinds of thing, and each kind is governed by its own
    14	 * price rules: main items follow the price list, components may form blocks.
    15	 * Both of a kind's figures -- what insuring it costs and what it is insured
    16	 * for -- come from those same rules, as the spec states them together.
    17	 *
    18	 * This module is the one place that decides which rules govern an item, so
    19	 * that a new kind of insurable thing is added here and nowhere else.
    20	 */
    21	
    22	/**
    23	 * Components are insured at a flat rate and carry no item-specific risk:
    24	 * a rune has neither an enchantment level nor a material to be cursed.
    25	 */
    26	function priceComponents(components: readonly Item[]): ItemPricing {
    27	  return {
    28	    basePremium: componentsBasePremium(components),
    29	    riskSurcharges: 0,
    30	  };
