     1	import type { Item } from "./policy.js";
     2	
     3	/**
     4	 * The price rules governing components such as runes and moonstones: what
     5	 * each is insured for, and what insuring them costs -- including the
     6	 * building block, the one concession that makes components cheaper than
     7	 * their number alone would suggest.
     8	 */
     9	
    10	/** Components such as runes and moonstones share one base premium. */
    11	const COMPONENT_BASE_PREMIUM = 25;
    12	
    13	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
    14	
    15	/**
    16	 * Each component is insured for its own value. The building block is a
    17	 * premium concession only: it never reduces what a component is insured for.
    18	 */
    19	export const COMPONENT_INSURANCE_VALUE = 250;
    20	
    21	/** A building block of alike components is offered at a special premium. */
    22	const COMPONENT_BLOCK_SIZE = 3;
    23	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
    24	
    25	export function isComponent(item: Item): boolean {
    26	  return COMPONENT_TYPES.includes(item.type);
    27	}
    28	
    29	/** Components count as "alike" -- and so may form a block -- per item type. */
    30	function alikeGroupSizes(components: readonly Item[]): readonly number[] {
    31	  const sizes = new Map<string, number>();
    32	  for (const component of components) {
    33	    sizes.set(component.type, (sizes.get(component.type) ?? 0) + 1);
    34	  }
    35	  return [...sizes.values()];
    36	}
    37	
    38	/**
    39	 * A block requires *exactly* the block size: 4 or 7 alike components are
    40	 * priced per component, not as blocks plus a remainder.
    41	 */
    42	function alikeGroupBasePremium(groupSize: number): number {
    43	  if (groupSize === COMPONENT_BLOCK_SIZE) {
    44	    return COMPONENT_BLOCK_BASE_PREMIUM;
    45	  }
    46	  return groupSize * COMPONENT_BASE_PREMIUM;
    47	}
    48	
    49	export function componentsBasePremium(components: readonly Item[]): number {
    50	  return alikeGroupSizes(components).reduce(
    51	    (sum, groupSize) => sum + alikeGroupBasePremium(groupSize),
    52	    0,
    53	  );
    54	}
