import type { Item } from "./policy.js";

export interface Damage {
  readonly itemType: string;
  readonly amount: number;
}

export interface ClaimResult {
  readonly payout: number;
  readonly remainingCap: number;
}

/**
 * The policyholder bears a deductible on each damaged item, so an incident
 * that damages several items bears it several times -- once per damage
 * entry, which is why the payout is accumulated per entry rather than off
 * the incident's total.
 */
const DEDUCTIBLE = 100;

/**
 * How much of a damage the MHPCO reimburses, before the deductible. No
 * special clause has an active example yet, so a damage is reimbursed in
 * full.
 */
function reimbursedAmount(_item: Item | undefined, damage: Damage): number {
  return damage.amount;
}

/** The damaged item, whose properties the special clauses will be read off. */
function damagedItem(
  items: readonly Item[],
  damage: Damage,
): Item | undefined {
  return items.find((item) => item.type === damage.itemType);
}

/** What one damage settles at: the reimbursement, less the deductible. */
function payoutForDamage(items: readonly Item[], damage: Damage): number {
  return Math.max(reimbursedAmount(damagedItem(items, damage), damage) - DEDUCTIBLE, 0);
}

/**
 * Settling an incident against the policy that covers it. The items are what
 * the special clauses and the rejection rules will be read off, once their
 * examples are active.
 */
export function claim(
  items: readonly Item[],
  damages: readonly Damage[],
  remainingCap: number,
): ClaimResult {
  const payout = damages.reduce(
    (total, damage) => total + payoutForDamage(items, damage),
    0,
  );
  return { payout, remainingCap: remainingCap - payout };
}
